mapper.select:
SELECT F.SEQ_NO as seqNo,/**流水号**/ F.FINPROD_ID as finprodId,/**资产id**/ FP.FINPROD_NAME as finprodValue,/**资产名称**/ F.STAGE as stage,/**阶段**/ F.EFF_DATE as effDate,/**生成日期**/ F.INVALID_DATE as invalidDate/**失效日期**/ FROM FIN_PRODUCT_LOSS_STAGE F left join FIN_PRODUCT FP on F.FINPROD_ID = FP.FINPROD_ID where 1=1
and F.FINPROD_ID=#{finprodId}
and F.STAGE=#{stage}
AND F.EFF_DATE >= to_date(#{startDate},'yyyy-MM-dd')
AND F.EFF_DATE <= to_date(#{endDate},'yyyy-MM-dd')

select F.SEQ_NO as seqNo, F.INVALID_DATE as invalidDate from FIN_PRODUCT_LOSS_STAGE F where 1=1
and F.EFF_DATE < #{effDate,jdbcType=TIMESTAMP}
and F.FINPROD_ID=#{finprodId}
order by F.EFF_DATE desc

select F.SEQ_NO as seqNo, F.EFF_DATE as effDate from FIN_PRODUCT_LOSS_STAGE F where 1=1
and F.EFF_DATE > #{effDate,jdbcType=TIMESTAMP}
and F.FINPROD_ID=#{finprodId}
order by F.EFF_DATE asc

mapper.update:
        update FIN_PRODUCT_LOSS_STAGE F
        set F.INVALID_DATE = #{invalidDate,jdbcType=TIMESTAMP}
        where 1=1
--         and F.INVALID_DATE is null

            and F.SEQ_NO = #{seqNo,jdbcType=VARCHAR}
